import json
from pathlib import Path
from .validation import validate

def load(path):
    records=[]
    for number,line in enumerate(Path(path).read_text().splitlines(), 1):
        if not line.strip():
            continue
        try:
            row=json.loads(line)
        except json.JSONDecodeError:
            raise ValueError(f"line {number}: invalid JSON")
        validate(row, number)
        records.append(row)
    return records

scattered.parcel/validation.py:
def validate(row, number):
    if not isinstance(row, dict):
        raise ValueError(f"line {number}: expected object")
    if not isinstance(row.get("tenant"),str) or not isinstance(row.get("id"),str):
        raise ValueError(f"line {number}: tenant and id must be strings")

scattered.parcel/selection.py:
def select(records, tenant=None):
    chosen=[]
    seen=set()
    for row in records:
        if tenant is not None and row["tenant"]!=tenant:
            continue
        key=(row["tenant"], row["id"])
        if key in seen:
            continue
        seen.add(key)
        chosen.append(row)
    return chosen

scattered.parcel/render.py:
import json

def render(records):
    return "".join(json.dumps(row,sort_keys=True)+"\n" for row in records)

